{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "MobileNav",
    "displayName": "Mobile Nav",
    "group": "Navigation",
    "category": "Navigation",
    "isHiddenFromOverview": true,
    "keywords": [
      "mobilenav",
      "drawer",
      "sidebar",
      "navigation",
      "hamburger",
      "menu",
      "offcanvas",
      "slideout",
      "navdrawer",
      "toggle"
    ],
    "components": [
      {
        "name": "MobileNav",
        "displayName": "Mobile Nav",
        "description": "A slide-out drawer for mobile navigation. Accepts SideNav children.",
        "playground": {
          "overlay": true,
          "defaults": {
            "isOpen": false,
            "header": "Navigation",
            "children": {
              "__element": "SideNavSection",
              "props": {
                "title": "Main"
              },
              "children": [
                {
                  "__element": "SideNavItem",
                  "props": {
                    "label": "Dashboard",
                    "isSelected": true
                  }
                },
                {
                  "__element": "SideNavItem",
                  "props": {
                    "label": "Projects"
                  }
                },
                {
                  "__element": "SideNavItem",
                  "props": {
                    "label": "Settings"
                  }
                }
              ]
            }
          }
        },
        "props": [
          {
            "name": "isOpen",
            "type": "boolean",
            "description": "Whether the drawer is open. Inside AppShell, this is managed automatically via context. Outside AppShell, provide this prop to control the drawer yourself."
          },
          {
            "name": "onOpenChange",
            "type": "(isOpen: boolean) => void",
            "description": "Called when the drawer visibility changes (backdrop click, Escape key, or close button). Inside AppShell, this is managed automatically via context. On a phone or tablet (a coarse primary pointer), the drawer takes no tap or drag while it slides in; keys and assistive technology still act. After a close, focus returns to the element that opened it once its dialog closes."
          },
          {
            "name": "children",
            "type": "ReactNode",
            "description": "Drawer content: typically SideNavSection/SideNavItem, or any ReactNode.",
            "required": true
          },
          {
            "name": "header",
            "type": "ReactNode",
            "description": "Header content for the drawer. Rendered next to the close button. Pass a string for a simple text heading, or a ReactNode for custom content (logo, search bar, etc.)."
          },
          {
            "name": "width",
            "type": "number",
            "description": "Drawer width in pixels. Capped at 85vw to prevent overflow on small screens.",
            "default": "320"
          },
          {
            "name": "side",
            "type": "'start' | 'end' | 'auto'",
            "description": "Which side the drawer slides from. Start is left in LTR, right in RTL. Auto picks a side based on the trigger position.",
            "default": "'auto'"
          }
        ]
      },
      {
        "name": "MobileNavToggle",
        "displayName": "Mobile Nav Toggle",
        "description": "Hamburger button that opens/closes the mobile nav drawer. Reads open state from AppShell context automatically: does NOT accept isOpen or onOpenChange props. Renders nothing above the mobile breakpoint. Host attributes and DOM handlers (id, data-*, aria-*) reach the button; its aria-expanded and aria-controls stay component-owned, and a caller onClick runs after the toggle.",
        "playground": {
          "appShellMobile": true
        },
        "props": [
          {
            "name": "children",
            "type": "ReactNode",
            "description": "Custom content to render instead of the default hamburger icon."
          },
          {
            "name": "label",
            "type": "string",
            "description": "Accessible label for the toggle button.",
            "default": "'Open navigation'"
          }
        ]
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-mobile-nav",
          "visualProps": [
            "side"
          ]
        }
      ]
    },
    "usage": {
      "anatomy": [
        {
          "name": "Navigation overlay",
          "required": true,
          "description": "Full-viewport dialog overlay that hosts the mobile navigation drawer."
        },
        {
          "name": "Drawer",
          "required": true,
          "description": "Painted panel that slides in from the resolved viewport edge."
        },
        {
          "name": "Header",
          "required": true,
          "description": "Fixed row containing optional header content and the close button."
        },
        {
          "name": "Content",
          "required": true,
          "description": "Scrollable region containing the navigation content."
        },
        {
          "name": "Close button",
          "required": true,
          "description": "Button that closes the navigation drawer."
        },
        {
          "name": "Toggle button",
          "required": false,
          "description": "AppShell-aware Button that opens or closes the drawer on mobile viewports."
        }
      ],
      "description": "A slide-out drawer for mobile navigation. MobileNav is the mobile counterpart to SideNav and accepts the same children. Use it on narrow viewports where a persistent sidebar is not practical. Inside AppShell, use MobileNavToggle as the trigger; it reads state from context automatically.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Share the same nav items between MobileNav and SideNav by extracting them into a variable."
        },
        {
          "guidance": true,
          "description": "Provide a header when the drawer's purpose is not obvious from its content."
        },
        {
          "guidance": true,
          "description": "Inside AppShell, use MobileNavToggle to open the drawer; it reads state from context. Do not pass isOpen/onOpenChange to the toggle."
        },
        {
          "guidance": false,
          "description": "Use MobileNav on desktop: use a persistent SideNav instead."
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/MobileNav",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
